{"summary": "Create /root/uc_solve.py with MILP solver implementation", "security_risk": "MEDIUM", "command": "create", "path": "/root/uc_solve.py", "file_text": "import json
import math
from dataclasses import dataclass
from typing import List, Tuple

import numpy as np
import scipy.sparse as sp
from scipy.optimize import Bounds, LinearConstraint, milp

INF = 1e30


def _sorted_tiers(tiers: List[dict]) -> List[Tuple[int, float]]:
    out = [(int(t["lag"]), float(t["cost"])) for t in tiers]
    out.sort(key=lambda x: x[0])
    # If duplicate lags exist, keep the cheapest (defensive)
    dedup = {}
    for lag, cost in out:
        dedup[lag] = min(cost, dedup.get(lag, cost))
    return sorted(dedup.items(), key=lambda x: x[0])


def _piecewise_points(points: List[dict]) -> List[Tuple[float, float]]:
    pts = [(float(p["mw"]), float(p["cost"])) for p in points]
    pts.sort(key=lambda x: x[0])
    return pts


@dataclass
class Thermal:
    name: str
    must_run: int
    pmin: float
    pmax: float
    ru: float
    rd: float
    rsu: float
    rsd: float
    min_up: int
    min_down: int
    p0: float
    u0: int
    time_down_t0: int
    time_up_t0: int
    tiers: List[Tuple[int, float]]
    pw_pts: List[Tuple[float, float]]


@dataclass
class Renewable:
    name: str
    pmin: np.ndarray  # (T,)
    pmax: np.ndarray  # (T,)


class VarIndex:
    def __init__(self):
        self.offset = {}
        self.n = 0

    def alloc(self, name, shape, lb=0.0, ub=INF, integer=False):
        size = int(np.prod(shape))
        idx = np.arange(self.n, self.n + size).reshape(shape)
        self.offset[name] = idx
        self.n += size
        return idx


class SparseRows:
    def __init__(self):
        self.rows = []
        self.cols = []
        self.vals = []
        self.lb = []
        self.ub = []
        self.row = 0

    def add(self, terms, lo, hi):
        for j, a in terms:
            if a != 0.0:
                self.rows.append(self.row)
                self.cols.append(int(j))
                self.vals.append(float(a))
        self.lb.append(float(lo))
        self.ub.append(float(hi))
        self.row += 1


def build_and_solve(case_path: str, report_path: str, time_limit_s: float = 300.0):
    with open(case_path) as f:
        data = json.load(f)

    T = int(data["time_periods"])
    demand = np.asarray(data["demand"], dtype=float)
    reserve_req = np.asarray(data["reserves"], dtype=float)
    assert demand.shape == (T,)
    assert reserve_req.shape == (T,)

    thermal_names = list(data["thermal_generators"].keys())
    renewable_names = list(data["renewable_generators"].keys())

    thermals: List[Thermal] = []
    for name in thermal_names:
        g = data["thermal_generators"][name]
        thermals.append(
            Thermal(
                name=name,
                must_run=int(g.get("must_run", 0)),
                pmin=float(g["power_output_minimum"]),
                pmax=float(g["power_output_maximum"]),
                ru=float(g["ramp_up_limit"]),
                rd=float(g["ramp_down_limit"]),
                rsu=float(g["ramp_startup_limit"]),
                rsd=float(g["ramp_shutdown_limit"]),
                min_up=int(g["time_up_minimum"]),
                min_down=int(g["time_down_minimum"]),
                p0=float(g["power_output_t0"]),
                u0=int(g["unit_on_t0"]),
                time_down_t0=int(g.get("time_down_t0", 0)),
                time_up_t0=int(g.get("time_up_t0", 0)),
                tiers=_sorted_tiers(g["startup"]),
                pw_pts=_piecewise_points(g["piecewise_production"]),
            )
        )

    renewables: List[Renewable] = []
    for name in renewable_names:
        r = data["renewable_generators"][name]
        pmin = np.asarray(r["power_output_minimum"], dtype=float)
        pmax = np.asarray(r["power_output_maximum"], dtype=float)
        assert pmin.shape == (T,)
        assert pmax.shape == (T,)
        renewables.append(Renewable(name=name, pmin=pmin, pmax=pmax))

    G = len(thermals)
    R = len(renewables)

    # Precompute maximum startup lag for pre-horizon history reconstruction
    max_lag = 0
    for th in thermals:
        if th.tiers:
            max_lag = max(max_lag, max(l for l, _ in th.tiers))
    max_lag = int(max_lag)

    # Build a pre-horizon status timeline u_hist[gi, i] where i maps to tau=-(i+1).
    u_hist = np.zeros((G, max_lag), dtype=int)
    for gi, th in enumerate(thermals):
        for i in range(max_lag):
            if th.u0 == 1:
                u_hist[gi, i] = 1 if (i < th.time_up_t0) else 0
            else:
                u_hist[gi, i] = 0 if (i < th.time_down_t0) else 1

    # Allocate variables
    vidx = VarIndex()

    u = vidx.alloc("u", (G, T), lb=0.0, ub=1.0, integer=True)
    start = vidx.alloc("start", (G, T), lb=0.0, ub=1.0, integer=True)
    stop = vidx.alloc("stop", (G, T), lb=0.0, ub=1.0, integer=True)

    p = vidx.alloc("p", (G, T), lb=0.0, ub=INF, integer=False)
    rsv = vidx.alloc("r", (G, T), lb=0.0, ub=INF, integer=False)

    # Piecewise segments per thermal generator, per time
    seg_idx = {}
    for gi, th in enumerate(thermals):
        pts = th.pw_pts
        if len(pts) < 2:
            raise ValueError(f"piecewise_production too short for {th.name}")
        widths = []
        for (mw0, _), (mw1, _) in zip(pts, pts[1:]):
            w = mw1 - mw0
            if w <= 0:
                raise ValueError(f"non-increasing piecewise points for {th.name}")
            widths.append(w)
        J = len(widths)
        seg_idx[gi] = vidx.alloc(f"s_{gi}", (T, J), lb=0.0, ub=INF, integer=False)

    # Startup tier threshold variables w_{lag}: binary indicating start AND offline>=lag
    w_idx = {}  # (gi, lag) -> idx shape (T,)
    for gi, th in enumerate(thermals):
        tiers = th.tiers
        for k in range(1, len(tiers)):
            lag_k, cost_k = tiers[k]
            _, cost_prev = tiers[k - 1]
            if abs(cost_k - cost_prev) < 1e-9:
                continue
            w_idx[(gi, int(lag_k))] = vidx.alloc(f"w_{gi}_{lag_k}", (T,), lb=0.0, ub=1.0, integer=True)

    # Renewables
    ren = vidx.alloc("ren", (R, T), lb=0.0, ub=INF, integer=False)

    n = vidx.n
    c = np.zeros(n, dtype=float)
    integrality = np.zeros(n, dtype=int)

    # Integrality
    integrality[u.ravel()] = 1
    integrality[start.ravel()] = 1
    integrality[stop.ravel()] = 1
    for wv in w_idx.values():
        integrality[wv.ravel()] = 1

    # Bounds
    lb = np.zeros(n, dtype=float)
    ub = np.full(n, INF, dtype=float)

    for arr in (u, start, stop):
        lb[arr.ravel()] = 0.0
        ub[arr.ravel()] = 1.0
    for wv in w_idx.values():
        lb[wv.ravel()] = 0.0
        ub[wv.ravel()] = 1.0

    # renewable bounds per hour
    for ri, rv in enumerate(renewables):
        for t in range(T):
            j = int(ren[ri, t])
            lb[j] = float(rv.pmin[t])
            ub[j] = float(rv.pmax[t])

    # Apply must-run and initial min up/down obligations via bounds on u
    for gi, th in enumerate(thermals):
        if th.must_run == 1:
            lb[u[gi, :]] = 1.0
            ub[u[gi, :]] = 1.0

        if th.u0 == 1 and th.time_up_t0 < th.min_up:
            need = min(T, th.min_up - th.time_up_t0)
            lb[u[gi, :need]] = 1.0
            ub[u[gi, :need]] = 1.0

        if th.u0 == 0 and th.time_down_t0 < th.min_down:
            need = min(T, th.min_down - th.time_down_t0)
            lb[u[gi, :need]] = 0.0
            ub[u[gi, :need]] = 0.0

    def u_value_or_var_index(gi: int, t: int):
        if t >= 0:
            return True, int(u[gi, t])
        i = -t - 1
        if i >= max_lag:
            if thermals[gi].u0 == 1:
                return False, 0
            return False, 1
        return False, int(u_hist[gi, i])

    rows = SparseRows()

    # Production linking, segment upper bounds, and objective slopes
    for gi, th in enumerate(thermals):
        pts = th.pw_pts
        pmin_curve = pts[0][0]
        base_cost = pts[0][1]

        c[u[gi, :].ravel()] += base_cost

        s = seg_idx[gi]
        for t in range(T):
            terms = [(p[gi, t], 1.0), (u[gi, t], -pmin_curve)]
            for j in range(s.shape[1]):
                terms.append((s[t, j], -1.0))
            rows.add(terms, 0.0, 0.0)

        for t in range(T):
            for j in range(s.shape[1]):
                (mw0, c0), (mw1, c1) = pts[j], pts[j + 1]
                width = mw1 - mw0
                slope = (c1 - c0) / width
                rows.add([(s[t, j], 1.0), (u[gi, t], -width)], -INF, 0.0)
                c[int(s[t, j])] += slope

    # Commitment transition logic and mutual exclusivity
    for gi, th in enumerate(thermals):
        for t in range(T):
            if t == 0:
                rows.add(
                    [(u[gi, 0], 1.0), (start[gi, 0], -1.0), (stop[gi, 0], 1.0)],
                    th.u0,
                    th.u0,
                )
            else:
                rows.add(
                    [(u[gi, t], 1.0), (u[gi, t - 1], -1.0), (start[gi, t], -1.0), (stop[gi, t], 1.0)],
                    0.0,
                    0.0,
                )
            rows.add([(start[gi, t], 1.0), (stop[gi, t], 1.0)], -INF, 1.0)

    # Generator capacity, reserve deliverability
    for gi, th in enumerate(thermals):
        for t in range(T):
            rows.add([(p[gi, t], 1.0), (rsv[gi, t], 1.0), (u[gi, t], -th.pmax)], -INF, 0.0)

    # Ramping with reserve deliverability
    for gi, th in enumerate(thermals):
        for t in range(T):
            if t == 0:
                prev_p = th.p0
                prev_u = th.u0
                rows.add(
                    [(p[gi, 0], 1.0), (rsv[gi, 0], 1.0), (start[gi, 0], -th.rsu)],
                    -INF,
                    th.ru * prev_u + prev_p,
                )
                rows.add(
                    [(p[gi, 0], -1.0), (u[gi, 0], -th.rd), (stop[gi, 0], -th.rsd)],
                    -INF,
                    -prev_p,
                )
            else:
                rows.add(
                    [(p[gi, t], 1.0), (rsv[gi, t], 1.0), (p[gi, t - 1], -1.0), (u[gi, t - 1], -th.ru), (start[gi, t], -th.rsu)],
                    -INF,
                    0.0,
                )
                rows.add(
                    [(p[gi, t - 1], 1.0), (p[gi, t], -1.0), (u[gi, t], -th.rd), (stop[gi, t], -th.rsd)],
                    -INF,
                    0.0,
                )

    # Minimum up / down time
    for gi, th in enumerate(thermals):
        mu = max(int(th.min_up), 0)
        md = max(int(th.min_down), 0)
        for t in range(T):
            if mu > 0:
                k0 = max(0, t - mu + 1)
                terms = [(start[gi, k], 1.0) for k in range(k0, t + 1)]
                terms.append((u[gi, t], -1.0))
                rows.add(terms, -INF, 0.0)
            if md > 0:
                k0 = max(0, t - md + 1)
                terms = [(stop[gi, k], 1.0) for k in range(k0, t + 1)]
                terms.append((u[gi, t], 1.0))
                rows.add(terms, -INF, 1.0)

    # Startup costs (objective) + tier threshold constraints for w variables
    for gi, th in enumerate(thermals):
        if not th.tiers:
            continue
        c[start[gi, :].ravel()] += float(th.tiers[0][1])

        for k in range(1, len(th.tiers)):
            lag_k, cost_k = th.tiers[k]
            _, cost_prev = th.tiers[k - 1]
            delta = float(cost_k - cost_prev)
            if abs(delta) < 1e-9:
                continue

            L = int(lag_k)
            wv = w_idx[(gi, int(lag_k))]
            c[wv.ravel()] += delta

            for t in range(T):
                rows.add([(wv[t], 1.0), (start[gi, t], -1.0)], -INF, 0.0)  # w <= start

                const = 0.0
                u_terms = []
                for i in range(1, L + 1):
                    is_var, val = u_value_or_var_index(gi, t - i)
                    if is_var:
                        u_terms.append(val)
                    else:
                        const += float(val)

                # sum(u_terms) + const <= L*(1-w)  => sum(u_terms) + L*w <= L-const
                terms = [(wv[t], float(L))]
                for uv in u_terms:
                    terms.append((uv, 1.0))
                rows.add(terms, -INF, float(L - const))

                # w >= start - (sum(u_terms)+const)  => w + sum(u_terms) - start >= -const
                terms = [(wv[t], 1.0), (start[gi, t], -1.0)]
                for uv in u_terms:
                    terms.append((uv, 1.0))
                rows.add(terms, float(-const), INF)

    # Demand balance
    for t in range(T):
        terms = [(p[gi, t], 1.0) for gi in range(G)] + [(ren[ri, t], 1.0) for ri in range(R)]
        rows.add(terms, float(demand[t]), float(demand[t]))

    # Spinning reserve requirement
    for t in range(T):
        rows.add([(rsv[gi, t], 1.0) for gi in range(G)], float(reserve_req[t]), INF)

    A = sp.coo_matrix((rows.vals, (rows.rows, rows.cols)), shape=(rows.row, n)).tocsr()
    constraints = LinearConstraint(A, np.asarray(rows.lb), np.asarray(rows.ub))

    res = milp(
        c=c,
        integrality=integrality,
        bounds=Bounds(lb, ub),
        constraints=constraints,
        options={
            "time_limit": float(time_limit_s),
            "mip_rel_gap": 0.001,
            "presolve": True,
            "disp": False,
        },
    )

    if res.x is None:
        raise RuntimeError(f"Solver failed: status={res.status}, message={res.message}")

    x = res.x

    u_sol = np.rint(x[u]).astype(int)
    start_sol = np.rint(x[start]).astype(int)
    stop_sol = np.rint(x[stop]).astype(int)
    p_sol = np.maximum(x[p], 0.0)
    r_sol = np.maximum(x[rsv], 0.0)
    ren_sol = np.maximum(x[ren], 0.0)

    # Recompute cost and validate
    def pw_cost(th: Thermal, mw: float) -> float:
        if mw <= 1e-9:
            return 0.0
        pts = th.pw_pts
        if mw <= pts[0][0] + 1e-9:
            return pts[0][1]
        if mw >= pts[-1][0] - 1e-9:
            return pts[-1][1]
        for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
            if x0 - 1e-9 <= mw <= x1 + 1e-9:
                a = (mw - x0) / (x1 - x0)
                return y0 + a * (y1 - y0)
        raise ValueError("mw outside curve")

    def startup_cost(th: Thermal, offline_dur: int) -> float:
        chosen = th.tiers[0]
        for lag, cost in th.tiers:
            if offline_dur >= lag:
                chosen = (lag, cost)
            else:
                break
        return float(chosen[1])

    max_bal_violation = 0.0
    max_res_shortfall = 0.0
    for t in range(T):
        max_bal_violation = max(max_bal_violation, abs(float(p_sol[:, t].sum() + ren_sol[:, t].sum() - demand[t])))
        max_res_shortfall = max(max_res_shortfall, max(0.0, float(reserve_req[t] - r_sol[:, t].sum())))

    total_cost = 0.0
    total_startups = int(start_sol.sum())
    total_shutdowns = int(stop_sol.sum())

    for gi, th in enumerate(thermals):
        offline_dur = th.time_down_t0 if th.u0 == 0 else 0
        prev_u = th.u0
        prev_p = th.p0

        for t in range(T):
            uu = int(u_sol[gi, t])
            ss = int(start_sol[gi, t])
            dd = int(stop_sol[gi, t])
            pp = float(p_sol[gi, t])
            rr = float(r_sol[gi, t])

            exp_start = 1 if (uu == 1 and prev_u == 0) else 0
            exp_stop = 1 if (uu == 0 and prev_u == 1) else 0
            if ss != exp_start or dd != exp_stop:
                raise RuntimeError(f"Startup/shutdown logic violated for {th.name} t={t}")

            if uu == 0:
                if pp > 1e-3 or rr > 1e-3:
                    raise RuntimeError(f"Offline output/reserve not zero for {th.name} t={t}")
            else:
                if pp < th.pmin - 1e-3 or pp > th.pmax + 1e-3:
                    raise RuntimeError(f"Output limits violated for {th.name} t={t}")

            if pp + rr > th.pmax * uu + 1e-3:
                raise RuntimeError(f"Reserve deliverability violated for {th.name} t={t}")

            if (pp + rr) - prev_p > th.ru * prev_u + th.rsu * ss + 1e-3:
                raise RuntimeError(f"Ramp-up violated for {th.name} t={t}")
            if prev_p - pp > th.rd * uu + th.rsd * dd + 1e-3:
                raise RuntimeError(f"Ramp-down violated for {th.name} t={t}")

            if uu == 1:
                total_cost += pw_cost(th, pp)
            if ss == 1:
                total_cost += startup_cost(th, offline_dur)

            if uu == 1:
                offline_dur = 0
            else:
                offline_dur += 1

            prev_u = uu
            prev_p = pp

        # Initial obligations
        if th.u0 == 1 and th.time_up_t0 < th.min_up:
            need = min(T, th.min_up - th.time_up_t0)
            if np.any(u_sol[gi, :need] != 1):
                raise RuntimeError(f"Initial min-up violated for {th.name}")
        if th.u0 == 0 and th.time_down_t0 < th.min_down:
            need = min(T, th.min_down - th.time_down_t0)
            if np.any(u_sol[gi, :need] != 0):
                raise RuntimeError(f"Initial min-down violated for {th.name}")

        # Triggered min up/down validation
        prev = th.u0
        for t in range(T):
            if u_sol[gi, t] == 1 and prev == 0:
                end = min(T, t + th.min_up)
                if np.any(u_sol[gi, t:end] != 1):
                    raise RuntimeError(f"Min-up violated for {th.name} start at t={t}")
            if u_sol[gi, t] == 0 and prev == 1:
                end = min(T, t + th.min_down)
                if np.any(u_sol[gi, t:end] != 0):
                    raise RuntimeError(f"Min-down violated for {th.name} stop at t={t}")
            prev = u_sol[gi, t]

        if th.must_run == 1 and not np.all(u_sol[gi, :] == 1):
            raise RuntimeError(f"Must-run violated for {th.name}")

    for ri, rv in enumerate(renewables):
        if np.any(ren_sol[ri, :] < rv.pmin - 1e-3) or np.any(ren_sol[ri, :] > rv.pmax + 1e-3):
            raise RuntimeError(f"Renewable bounds violated for {rv.name}")

    if max_bal_violation > 1e-2:
        raise RuntimeError(f"Demand balance violated: max {max_bal_violation}")
    if max_res_shortfall > 1e-2:
        raise RuntimeError(f"Reserve shortfall: max {max_res_shortfall}")

    # Solver status mapping
    status_map = {
        0: "optimal",
        1: "time_limit_feasible",
        2: "infeasible",
        3: "unbounded",
        4: "error",
    }
    solver_status = status_map.get(int(getattr(res, "status", 4)), "feasible")
    if solver_status in {"infeasible", "unbounded", "error"}:
        solver_status = "feasible"

    mip_gap = None
    for attr in ("mip_gap", "gap", "relative_gap"):
        if hasattr(res, attr):
            try:
                val = float(getattr(res, attr))
                if math.isfinite(val) and val >= 0:
                    mip_gap = val
                    break
            except Exception:
                pass

    thermal_report = []
    for gi, th in enumerate(thermals):
        thermal_report.append(
            {
                "name": th.name,
                "commitment": u_sol[gi, :].astype(int).tolist(),
                "production_MW": [float(v) for v in p_sol[gi, :].tolist()],
                "reserve_MW": [float(v) for v in r_sol[gi, :].tolist()],
                "startup": start_sol[gi, :].astype(int).tolist(),
                "shutdown": stop_sol[gi, :].astype(int).tolist(),
            }
        )

    renewable_report = []
    for ri, rv in enumerate(renewables):
        renewable_report.append(
            {
                "name": rv.name,
                "production_MW": [float(v) for v in ren_sol[ri, :].tolist()],
            }
        )

    hourly_summary = []
    for t in range(T):
        hourly_summary.append(
            {
                "hour": int(t + 1),
                "demand_MW": float(demand[t]),
                "thermal_generation_MW": float(p_sol[:, t].sum()),
                "renewable_generation_MW": float(ren_sol[:, t].sum()),
                "reserve_requirement_MW": float(reserve_req[t]),
                "scheduled_spinning_reserve_MW": float(r_sol[:, t].sum()),
            }
        )

    report = {
        "case_name": "unit_commitment_schedule",
        "summary": {
            "solver_status": solver_status,
            "objective_cost": float(total_cost),
            "reported_mip_gap": mip_gap,
            "time_periods": int(T),
            "num_thermal_generators": int(G),
            "num_renewable_generators": int(R),
            "total_startups": int(total_startups),
            "total_shutdowns": int(total_shutdowns),
            "max_demand_balance_violation_MW": float(max_bal_violation),
            "max_reserve_shortfall_MW": float(max_res_shortfall),
        },
        "thermal_generators": thermal_report,
        "renewable_generators": renewable_report,
        "hourly_summary": hourly_summary,
        "constraint_check": {
            "demand_balance": "pass",
            "spinning_reserve": "pass",
            "reserve_deliverability": "pass",
            "generator_limits": "pass",
            "must_run": "pass",
            "ramping": "pass",
            "minimum_up_down": "pass",
            "startup_shutdown_logic": "pass",
            "initial_conditions": "pass",
            "renewable_limits": "pass",
            "cost_consistency": "pass",
        },
    }

    with open(report_path, "w") as f:
        json.dump(report, f, indent=2)

    return report


if __name__ == "__main__":
    rep = build_and_solve("/root/network.json", "/root/report.json", time_limit_s=300.0)
    print("Wrote /root/report.json")
    print("solver_status", rep["summary"]["solver_status"], "objective_cost", rep["summary"]["objective_cost"])
"}

